     1→import type { BetterAuthClientPlugin } from "@better-auth/core";
     2→import type { DBFieldAttribute } from "@better-auth/core/db";
     3→import { atom } from "nanostores";
     4→import { useAuthQuery } from "../../client";
     5→import type {
     6→	InferInvitation,
     7→	InferMember,
     8→	InferOrganization,
     9→	InferTeam,
    10→	Member,
    11→} from "../../plugins/organization/schema";
    12→import type { BetterAuthOptions, BetterAuthPlugin } from "../../types";
    13→import type { Prettify } from "../../types/helper";
    14→import type { AccessControl, Role } from "../access";
    15→import type { defaultStatements } from "./access";
    16→import { adminAc, defaultRoles, memberAc, ownerAc } from "./access";
    17→import { ORGANIZATION_ERROR_CODES } from "./error-codes";
    18→import type { OrganizationPlugin } from "./organization";
    19→import type { HasPermissionBaseInput } from "./permission";
    20→import { hasPermissionFn } from "./permission";
    21→import type { OrganizationOptions } from "./types";
    22→
    23→export * from "./error-codes";
    24→
    25→/**
    26→ * Using the same `hasPermissionFn` function, but without the need for a `ctx` parameter or the `organizationId` parameter.
    27→ */
    28→export const clientSideHasPermission = (input: HasPermissionBaseInput) => {
    29→	const acRoles: {
    30→		[x: string]: Role<any> | undefined;
    31→	} = input.options.roles || defaultRoles;
    32→
    33→	return hasPermissionFn(input, acRoles);
    34→};
    35→
    36→interface OrganizationClientOptions {
    37→	ac?: AccessControl | undefined;
    38→	roles?:
    39→		| {
    40→				[key in string]: Role;
    41→		  }
    42→		| undefined;
    43→	teams?:
    44→		| {
    45→				enabled: boolean;
    46→		  }
    47→		| undefined;
    48→	schema?:
    49→		| {
    50→				organization?: {
    51→					additionalFields?: {
    52→						[key: string]: DBFieldAttribute;
    53→					};
    54→				};
    55→				member?: {
    56→					additionalFields?: {
    57→						[key: string]: DBFieldAttribute;
    58→					};
    59→				};
    60→				invitation?: {
    61→					additionalFields?: {
    62→						[key: string]: DBFieldAttribute;
    63→					};
    64→				};
    65→				team?: {
    66→					additionalFields?: {
    67→						[key: string]: DBFieldAttribute;
    68→					};
    69→				};
    70→				organizationRole?: {
    71→					additionalFields?: {
    72→						[key: string]: DBFieldAttribute;
    73→					};
    74→				};
    75→		  }
    76→		| undefined;
    77→	dynamicAccessControl?:
    78→		| {
    79→				enabled: boolean;
    80→		  }
    81→		| undefined;
    82→}
    83→
    84→export const organizationClient = <CO extends OrganizationClientOptions>(
    85→	options?: CO | undefined,
    86→) => {
    87→	const $listOrg = atom<boolean>(false);
    88→	const $activeOrgSignal = atom<boolean>(false);
    89→	const $activeMemberSignal = atom<boolean>(false);
    90→	const $activeMemberRoleSignal = atom<boolean>(false);
    91→
    92→	type DefaultStatements = typeof defaultStatements;
    93→	type Statements =
    94→		CO["ac"] extends AccessControl<infer S> ? S : DefaultStatements;
    95→	type PermissionType = {
    96→		[key in keyof Statements]?: Array<
    97→			Statements[key] extends readonly unknown[]
    98→				? Statements[key][number]
    99→				: never
   100→		>;
   101→	};
   102→	type PermissionExclusive = {
   103→		permissions: PermissionType;
   104→	};
   105→
   106→	const roles = {
   107→		admin: adminAc,
   108→		member: memberAc,
   109→		owner: ownerAc,
   110→		...options?.roles,
   111→	};
   112→
   113→	type OrganizationReturn = CO["teams"] extends { enabled: true }
   114→		? {
   115→				members: InferMember<CO>[];
   116→				invitations: InferInvitation<CO>[];
   117→				teams: InferTeam<CO>[];
   118→			} & InferOrganization<CO>
   119→		: {
   120→				members: InferMember<CO>[];
   121→				invitations: InferInvitation<CO>[];
   122→			} & InferOrganization<CO>;
   123→
   124→	type Schema = CO["schema"];
   125→	return {
   126→		id: "organization",
   127→		$InferServerPlugin: {} as OrganizationPlugin<{
   128→			ac: CO["ac"] extends AccessControl
   129→				? CO["ac"]
   130→				: AccessControl<DefaultStatements>;
   131→			roles: CO["roles"] extends Record<string, Role>
   132→				? CO["roles"]
   133→				: {
   134→						admin: Role;
   135→						member: Role;
   136→						owner: Role;
   137→					};
   138→			teams: {
   139→				enabled: CO["teams"] extends { enabled: true } ? true : false;
   140→			};
   141→			schema: Schema;
   142→			dynamicAccessControl: {
   143→				enabled: CO["dynamicAccessControl"] extends { enabled: true }
   144→					? true
   145→					: false;
   146→			};
   147→		}>,
   148→		getActions: ($fetch, _$store, co) => ({
   149→			$Infer: {
   150→				ActiveOrganization: {} as OrganizationReturn,
   151→				Organization: {} as InferOrganization<CO>,
   152→				Invitation: {} as InferInvitation<CO>,
   153→				Member: {} as InferMember<CO>,
   154→				Team: {} as InferTeam<CO>,
   155→			},
   156→			organization: {
   157→				checkRolePermission: <
   158→					R extends CO extends { roles: any }
   159→						? keyof CO["roles"]
   160→						: "admin" | "member" | "owner",
   161→				>(
   162→					data: PermissionExclusive & {
   163→						role: R;
   164→					},
   165→				) => {
   166→					const isAuthorized = clientSideHasPermission({
   167→						role: data.role as string,
   168→						options: {
   169→							ac: options?.ac,
   170→							roles: roles,
   171→						},
   172→						permissions: data.permissions as any,
   173→					});
   174→					return isAuthorized;
   175→				},
   176→			},
   177→		}),
   178→		getAtoms: ($fetch) => {
   179→			const listOrganizations = useAuthQuery<InferOrganization<CO>[]>(
   180→				$listOrg,
   181→				"/organization/list",
   182→				$fetch,
   183→				{
   184→					method: "GET",
   185→				},
   186→			);
   187→			const activeOrganization = useAuthQuery<
   188→				Prettify<
   189→					InferOrganization<CO> & {
   190→						members: InferMember<CO>[];
   191→						invitations: InferInvitation<CO>[];
   192→					}
   193→				>
   194→			>(
   195→				[$activeOrgSignal],
   196→				"/organization/get-full-organization",
   197→				$fetch,
   198→				() => ({
   199→					method: "GET",
   200→				}),
   201→			);
   202→
   203→			const activeMember = useAuthQuery<Member>(
   204→				[$activeOrgSignal, $activeMemberSignal],
   205→				"/organization/get-active-member",
   206→				$fetch,
   207→				{
   208→					method: "GET",
   209→				},
   210→			);
   211→
   212→			const activeMemberRole = useAuthQuery<{ role: string }>(
   213→				[$activeOrgSignal, $activeMemberRoleSignal],
   214→				"/organization/get-active-member-role",
   215→				$fetch,
   216→				{
   217→					method: "GET",
   218→				},
   219→			);
   220→
   221→			return {
   222→				$listOrg,
   223→				$activeOrgSignal,
   224→				$activeMemberSignal,
   225→				$activeMemberRoleSignal,
   226→				activeOrganization,
   227→				listOrganizations,
   228→				activeMember,
   229→				activeMemberRole,
   230→			};
   231→		},
   232→		pathMethods: {
   233→			"/organization/get-full-organization": "GET",
   234→			"/organization/list-user-teams": "GET",
   235→		},
   236→		atomListeners: [
   237→			{
   238→				matcher(path) {
   239→					return (
   240→						path === "/organization/create" ||
   241→						path === "/organization/delete" ||
   242→						path === "/organization/update"
   243→					);
   244→				},
   245→				signal: "$listOrg",
   246→			},
   247→			{
   248→				matcher(path) {
   249→					return path.startsWith("/organization");
   250→				},
   251→				signal: "$activeOrgSignal",
   252→			},
   253→			{
   254→				matcher(path) {
   255→					return (
   256→						path.startsWith("/organization/set-active") ||
   257→						path === "/organization/create" ||
   258→						path === "/organization/delete" ||
   259→						path === "/organization/remove-member" ||
   260→						path === "/organization/leave" ||
   261→						path === "/organization/accept-invitation"
   262→					);
   263→				},
   264→				signal: "$sessionSignal",
   265→			},
   266→		],
   267→		$ERROR_CODES: ORGANIZATION_ERROR_CODES,
   268→	} satisfies BetterAuthClientPlugin;
   269→};
   270→
   271→export const inferOrgAdditionalFields = <
   272→	O extends {
   273→		options: BetterAuthOptions;
   274→	},
   275→	S extends OrganizationOptions["schema"] = undefined,
   276→>(
   277→	schema?: S | undefined,
   278→) => {
   279→	type FindById<
   280→		T extends readonly BetterAuthPlugin[],
   281→		TargetId extends string,
   282→	> = Extract<T[number], { id: TargetId }>;
   283→
   284→	type Auth = O extends { options: any } ? O : { options: { plugins: [] } };
   285→
   286→	type OrganizationPlugin = FindById<
   287→		// @ts-expect-error
   288→		Auth["options"]["plugins"],
   289→		"organization"
   290→	>;
   291→
   292→	// The server schema can contain more properties other than additionalFields, but the client only supports additionalFields
   293→	// if we don't remove all other properties we may see assignability issues
   294→
   295→	type ExtractClientOnlyFields<T> = {
   296→		[K in keyof T]: T[K] extends { additionalFields: infer _AF }
   297→			? T[K]
   298→			: undefined;
   299→	};
   300→
   301→	type Schema = O extends Object
   302→		? O extends Exclude<OrganizationOptions["schema"], undefined>
   303→			? O
   304→			: OrganizationPlugin extends { options: { schema: infer S } }
   305→				? S extends OrganizationOptions["schema"]
   306→					? ExtractClientOnlyFields<S>
   307→					: undefined
   308→				: undefined
   309→		: undefined;
   310→	return {} as undefined extends S ? Schema : S;
   311→};
   312→
