    11→type InferSchema<
    12→	Schema extends BetterAuthPluginDBSchema,
    13→	TableName extends string,
    14→	DefaultFields,
    15→> = {
    16→	modelName: Schema[TableName] extends { modelName: infer M }
    17→		? M extends string
    18→			? M
    19→			: string
    20→		: string;
    21→	fields: {
    22→		[K in keyof DefaultFields]: DefaultFields[K];
    23→	} & (Schema[TableName] extends { additionalFields: infer F } ? F : {});
    24→};
