   205→export type OrganizationSchema<O extends OrganizationOptions> =
   206→	(O["dynamicAccessControl"] extends { enabled: true }
   207→		? {
   208→				organizationRole: InferSchema<
   209→					O["schema"] extends BetterAuthPluginDBSchema ? O["schema"] : {},
   210→					"organizationRole",
   211→					OrganizationRoleDefaultFields
   212→				>;
   213→			} & {
   214→				session: {
   215→					fields: InferSchema<
   216→						O["schema"] extends BetterAuthPluginDBSchema ? O["schema"] : {},
   217→						"session",
   218→						SessionDefaultFields
   219→					>["fields"];
   220→				};
   221→			}
   222→		: {}) &
   223→		(O["teams"] extends { enabled: true }
   224→			? {
   225→					team: InferSchema<
   226→						O["schema"] extends BetterAuthPluginDBSchema ? O["schema"] : {},
   227→						"team",
   228→						TeamDefaultFields
   229→					>;
   230→					teamMember: InferSchema<
   231→						O["schema"] extends BetterAuthPluginDBSchema ? O["schema"] : {},
   232→						"teamMember",
   233→						TeamMemberDefaultFields
   234→					>;
   235→				}
   236→			: {}) & {
   237→			organization: InferSchema<
   238→				O["schema"] extends BetterAuthPluginDBSchema ? O["schema"] : {},
   239→				"organization",
   240→				OrganizationDefaultFields
   241→			>;
   242→			member: InferSchema<
   243→				O["schema"] extends BetterAuthPluginDBSchema ? O["schema"] : {},
   244→				"member",
   245→				MemberDefaultFields
   246→			>;
   247→			invitation: {
   248→				modelName: O["schema"] extends BetterAuthPluginDBSchema
   249→					? InferSchema<
   250→							O["schema"],
   251→							"invitation",
   252→							InvitationDefaultFields
   253→						>["modelName"]
   254→					: string;
   255→				fields: InferSchema<
   256→					O["schema"] extends BetterAuthPluginDBSchema ? O["schema"] : {},
   257→					"invitation",
   258→					InvitationDefaultFields
   259→				>["fields"] &
   260→					(O extends { teams: { enabled: true } }
   261→						? {
