   159→const createHasPermissionBodySchema = z
   160→	.object({
   161→		organizationId: z.string().optional(),
   162→	})
   163→	.and(
   164→		z.union([
   165→			z.object({
   166→				permission: z.record(z.string(), z.array(z.string())),
   167→				permissions: z.undefined(),
   168→			}),
   169→			z.object({
   170→				permission: z.undefined(),
   171→				permissions: z.record(z.string(), z.array(z.string())),
   172→			}),
   173→		]),
   174→	);
