   176→const createHasPermission = <O extends OrganizationOptions>(options: O) => {
   177→	type DefaultStatements = typeof defaultStatements;
   178→	type Statements =
   179→		O["ac"] extends AccessControl<infer S> ? S : DefaultStatements;
   180→	type PermissionType = {
   181→		[key in keyof Statements]?: Array<
   182→			Statements[key] extends readonly unknown[]
   183→				? Statements[key][number]
   184→				: never
   185→		>;
   186→	};
   187→	type PermissionExclusive = {
   188→		permissions: PermissionType;
   189→	};
   190→
   191→	return createAuthEndpoint(
   192→		"/organization/has-permission",
   193→		{
   194→			method: "POST",
   195→			requireHeaders: true,
   196→			body: createHasPermissionBodySchema,
   197→			use: [orgSessionMiddleware],
   198→			metadata: {
   199→				$Infer: {
   200→					body: {} as PermissionExclusive & {
   201→						organizationId?: string | undefined;
   202→					},
   203→				},
   204→				openapi: {
   205→					description: "Check if the user has permission",
   206→					requestBody: {
   207→						content: {
   208→							"application/json": {
   209→								schema: {
   210→									type: "object",
   211→									properties: {
   212→										permission: {
   213→											type: "object",
   214→											description: "The permission to check",
   215→											deprecated: true,
   216→										},
   217→										permissions: {
   218→											type: "object",
   219→											description: "The permission to check",
   220→										},
   221→									},
   222→									required: ["permissions"],
   223→								},
   224→							},
   225→						},
   226→					},
   227→					responses: {
   228→						"200": {
   229→							description: "Success",
   230→							content: {
   231→								"application/json": {
   232→									schema: {
   233→										type: "object",
   234→										properties: {
   235→											error: {
   236→												type: "string",
   237→											},
   238→											success: {
   239→												type: "boolean",
   240→											},
   241→										},
   242→										required: ["success"],
   243→									},
   244→								},
   245→							},
   246→						},
   247→					},
   248→				},
   249→			},
   250→		},
   251→		async (ctx) => {
   252→			const activeOrganizationId =
   253→				ctx.body.organizationId ||
   254→				ctx.context.session.session.activeOrganizationId;
   255→			if (!activeOrganizationId) {
   256→				throw APIError.from(
   257→					"BAD_REQUEST",
   258→					ORGANIZATION_ERROR_CODES.NO_ACTIVE_ORGANIZATION,
   259→				);
   260→			}
   261→			const adapter = getOrgAdapter<O>(ctx.context, options);
   262→			const member = await adapter.findMemberByOrgId({
   263→				userId: ctx.context.session.user.id,
   264→				organizationId: activeOrganizationId,
   265→			});
   266→			if (!member) {
   267→				throw APIError.from(
   268→					"UNAUTHORIZED",
   269→					ORGANIZATION_ERROR_CODES.USER_IS_NOT_A_MEMBER_OF_THE_ORGANIZATION,
   270→				);
   271→			}
   272→			const result = await hasPermission(
   273→				{
   274→					role: member.role,
   275→					options: options,
   276→					permissions: ctx.body.permissions as any,
   277→					organizationId: activeOrganizationId,
   278→				},
   279→				ctx,
   280→			);
   281→
   282→			return ctx.json({
   283→				error: null,
   284→				success: result,
   285→			});
   286→		},
   287→	);
   288→};
