    12→export default function CreateOrganizationForm() {
    13→	const router = useRouter();
    14→
    15→	const form = useForm({
    16→		defaultValues: {
    17→			name: "",
    18→			slug: "",
    19→		},
    20→		onSubmit: async ({ value }) => {
    21→			try {
    22→				const result = await authClient.organization.create({
    23→					name: value.name,
    24→					slug: value.slug,
    25→				});
    26→
    27→				if (result.error) {
    28→					toast.error(result.error.message || "Failed to create organization");
    29→					return;
    30→				}
    31→
    32→				// Set the newly created organization as active
    33→				if (result.data?.id) {
    34→					await authClient.organization.setActive({
    35→						organizationId: result.data.id,
    36→					});
    37→				}
    38→
    39→				toast.success("Organization created successfully");
    40→				router.push("/dashboard");
    41→				router.refresh();
    42→			} catch (error) {
    43→				toast.error("An unexpected error occurred");
    44→			}
    45→		},
    46→		validators: {
    47→			onSubmit: z.object({
    48→				name: z.string().min(2, "Name must be at least 2 characters"),
    49→				slug: z
    50→					.string()
    51→					.min(2, "Slug must be at least 2 characters")
    52→					.max(50, "Slug must be at most 50 characters")
    53→					.regex(
    54→						/^[a-z0-9-]+$/,
    55→						"Slug can only contain lowercase letters, numbers, and hyphens",
    56→					),
    57→			}),
    58→		},
    59→	});
