     1→import { auth } from "@orksys-survey/auth";
     2→import { db } from "@orksys-survey/db";
     3→import { member, organization } from "@orksys-survey/db/schema/organization";
     4→import { and, eq } from "drizzle-orm";
     5→import type { NextRequest } from "next/server";
     6→
     7→export interface ActiveOrganization {
     8→	id: string;
     9→	name: string;
    10→	slug: string;
    11→	logo: string | null;
    12→}
    13→
    14→export interface Membership {
    15→	id: string;
    16→	role: "owner" | "admin" | "member";
    17→	organizationId: string;
    18→}
    19→
    20→export async function createContext(req: NextRequest) {
    21→	const session = await auth.api.getSession({
    22→		headers: req.headers,
    23→	});
    24→
    25→	if (!session || !session.user) {
    26→		return {
    27→			session: null,
    28→			activeOrganization: null,
    29→			membership: null,
    30→		};
    31→	}
    32→
    33→	// Get active organization ID from session
    34→	const activeOrgId = session.session.activeOrganizationId;
    35→
    36→	if (!activeOrgId) {
    37→		return {
    38→			session,
    39→			activeOrganization: null,
    40→			membership: null,
    41→		};
    42→	}
    43→
    44→	// Fetch organization and membership in parallel
    45→	const [orgResult, membershipResult] = await Promise.all([
    46→		db
    47→			.select({
    48→				id: organization.id,
    49→				name: organization.name,
    50→				slug: organization.slug,
    51→				logo: organization.logo,
    52→			})
    53→			.from(organization)
    54→			.where(eq(organization.id, activeOrgId))
    55→			.limit(1),
    56→		db
    57→			.select({
    58→				id: member.id,
    59→				role: member.role,
    60→				organizationId: member.organizationId,
    61→			})
    62→			.from(member)
    63→			.where(
    64→				and(
    65→					eq(member.userId, session.user.id),
    66→					eq(member.organizationId, activeOrgId),
    67→				),
    68→			)
    69→			.limit(1),
    70→	]);
    71→
    72→	const org = (orgResult[0] as ActiveOrganization | undefined) ?? null;
    73→	const membershipRecord =
    74→		(membershipResult[0] as Membership | undefined) ?? null;
    75→
    76→	return {
    77→		session,
    78→		activeOrganization: org,
    79→		membership: membershipRecord,
    80→	};
    81→}
    82→
    83→export type Context = Awaited<ReturnType<typeof createContext>>;
    84→

