     1→import type { NextRequest } from "next/server";
     2→import { NextResponse } from "next/server";
     3→
     4→const publicRoutes = ["/", "/login", "/onboarding", "/success", "/s"];
     5→const apiRoutes = ["/api"];
     6→
     7→async function getSession(request: NextRequest) {
     8→	try {
     9→		const baseUrl = request.nextUrl.origin;
    10→		const response = await fetch(`${baseUrl}/api/auth/get-session`, {
    11→			headers: {
    12→				cookie: request.headers.get("cookie") || "",
    13→			},
    14→		});
    15→
    16→		if (!response.ok) return null;
    17→		return await response.json();
    18→	} catch (error) {
    19→		console.error("Failed to fetch session in middleware:", error);
    20→		return null;
    21→	}
    22→}
    23→
    24→export async function middleware(request: NextRequest) {
    25→	const { pathname } = request.nextUrl;
    26→
    27→	// Allow public routes
    28→	if (
    29→		publicRoutes.some(
    30→			(route) => pathname === route || pathname.startsWith(route + "/"),
    31→		)
    32→	) {
    33→		// For onboarding page, check if user already has active org
    34→		if (pathname === "/onboarding") {
    35→			const session = await getSession(request);
    36→
    37→			if (!session?.user) {
    38→				return NextResponse.redirect(new URL("/login", request.url));
    39→			}
    40→
    41→			if (session.session.activeOrganizationId) {
    42→				return NextResponse.redirect(new URL("/dashboard", request.url));
    43→			}
    44→		}
    45→
    46→		return NextResponse.next();
    47→	}
    48→
    49→	// Allow API routes
    50→	if (apiRoutes.some((route) => pathname.startsWith(route))) {
    51→		return NextResponse.next();
    52→	}
    53→
    54→	// Protected routes - check authentication
    55→	const session = await getSession(request);
    56→
    57→	if (!session?.user) {
    58→		return NextResponse.redirect(new URL("/login", request.url));
    59→	}
    60→
    61→	// Check for active organization
    62→	if (!session.session.activeOrganizationId) {
    63→		return NextResponse.redirect(new URL("/onboarding", request.url));
    64→	}
    65→
    66→	return NextResponse.next();
    67→}
    68→
    69→export const config = {
    70→	matcher: [
    71→		/*
    72→		 * Match all request paths except for the ones starting with:
    73→		 * - _next/static (static files)
    74→		 * - _next/image (image optimization files)
    75→		 * - favicon.ico (favicon file)
    76→		 */
    77→		"/((?!_next/static|_next/image|favicon.ico).*)",
    78→	],
    79→};
    80→

