   297→			if (!member) {
   298→				throw APIError.from(
   299→					"BAD_REQUEST",
   300→					ORGANIZATION_ERROR_CODES.MEMBER_NOT_FOUND,
   301→				);
   302→			}
   303→			let toBeRemovedMember: InferMember<O> | null = null;
   304→			if (ctx.body.memberIdOrEmail.includes("@")) {
   305→				toBeRemovedMember = await adapter.findMemberByEmail({
   306→					email: ctx.body.memberIdOrEmail,
   307→					organizationId: organizationId,
   308→				});
   309→			} else {
   310→				const result = await adapter.findMemberById(ctx.body.memberIdOrEmail);
   311→				if (!result) toBeRemovedMember = null;
   312→				else {
   313→					const { user: _user, ...member } = result;
   314→					toBeRemovedMember = member as unknown as InferMember<O>;
   315→				}
   316→			}
   317→			if (!toBeRemovedMember) {
   318→				throw APIError.from(
   319→					"BAD_REQUEST",
   320→					ORGANIZATION_ERROR_CODES.MEMBER_NOT_FOUND,
   321→				);
   322→			}
   323→			const roles = toBeRemovedMember.role.split(",");
   324→			const creatorRole = ctx.context.orgOptions?.creatorRole || "owner";
   325→			const isOwner = roles.includes(creatorRole);
   326→			if (isOwner) {
