   332→				}
   333→				const { members } = await adapter.listMembers({
   334→					organizationId: organizationId,
   335→				});
   336→				const owners = members.filter((member) => {
   337→					const roles = member.role.split(",");
   338→					return roles.includes(creatorRole);
   339→				});
   340→				if (owners.length <= 1) {
   341→					throw APIError.from(
   342→						"BAD_REQUEST",
   343→						ORGANIZATION_ERROR_CODES.YOU_CANNOT_LEAVE_THE_ORGANIZATION_AS_THE_ONLY_OWNER,
   344→					);
   345→				}
   346→			}
   347→			const canDeleteMember = await hasPermission(
   348→				{
   349→					role: member.role,
   350→					options: ctx.context.orgOptions,
   351→					permissions: {
   352→						member: ["delete"],
   353→					},
   354→					organizationId,
   355→				},
