   385→				throw APIError.fromStatus("BAD_REQUEST", {
   386→					message: "User not found",
   387→				});
   388→			}
   389→
   390→			// Run beforeRemoveMember hook
   391→			if (options?.organizationHooks?.beforeRemoveMember) {
   392→				await options?.organizationHooks.beforeRemoveMember({
   393→					member: toBeRemovedMember,
   394→					user: userBeingRemoved,
   395→					organization,
   396→				});
   397→			}
   398→			await adapter.deleteMember({
   399→				memberId: toBeRemovedMember.id,
   400→				organizationId: organizationId,
   401→				userId: toBeRemovedMember.userId,
   402→			});
   403→			if (
   404→				session.user.id === toBeRemovedMember.userId &&
   405→				session.session.activeOrganizationId ===
   406→					toBeRemovedMember.organizationId
   407→			) {
   408→				await adapter.setActiveOrganization(session.session.token, null, ctx);
   409→			}
   410→
   411→			// Run afterRemoveMember hook
   412→			if (options?.organizationHooks?.afterRemoveMember) {
   413→				await options?.organizationHooks.afterRemoveMember({
   414→					member: toBeRemovedMember,
   415→					user: userBeingRemoved,
   416→					organization,
   417→				});
   418→			}
