   567→
   568→			const isUpdatingCreator = toBeUpdatedMemberRoles.includes(creatorRole);
   569→			const updaterIsCreator = updatingMemberRoles.includes(creatorRole);
   570→
   571→			const isSettingCreatorRole = roleToSet.includes(creatorRole);
   572→
   573→			const memberIsUpdatingThemselves = member.id === toBeUpdatedMember.id;
   574→
   575→			if (
