### 5. API Context (`/Users/orksys/Projects/orksys-survey/packages/api/src/context.ts`)

The oRPC context extracts session and active organization:

```typescript
export async function createContext(req: NextRequest) {
	const session = await auth.api.getSession({ headers: req.headers });

	if (!session || !session.user) {
		return { session: null, activeOrganization: null, membership: null };
	}

	const activeOrgId = session.session.activeOrganizationId;

	if (!activeOrgId) {
		return { session, activeOrganization: null, membership: null };
	}

	// Fetch organization and membership in parallel
	const [orgResult, membershipResult] = await Promise.all([
		db.select({...}).from(organization).where(eq(organization.id, activeOrgId)).limit(1),
		db.select({...}).from(member).where(and(
			eq(member.userId, session.user.id),
			eq(member.organizationId, activeOrgId),
		)).limit(1),
	]);

	return {
		session,
		activeOrganization: org,
		membership: membershipRecord,
	};
}
