    24→function getInitials(name: string): string {
    25→	const parts = name.trim().split(/\s+/);
    26→	if (parts.length === 1) {
    27→		return parts[0].charAt(0).toUpperCase();
    28→	}
    29→	return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
    30→}
