    62→							<AvatarFallback>
    63→								{session.user.name ? getInitials(session.user.name) : "?"}
    64→							</AvatarFallback>
    65→						</Avatar>
    66→					</Button>
    67→				}
    68→			/>
    69→			<DropdownMenuContent align="end" className="min-w-[220px] max-w-[300px]">
    70→				<DropdownMenuGroup>
    71→					<DropdownMenuLabel className="font-normal">
    72→						<div className="flex flex-col gap-1">
    73→							<p className="truncate font-medium text-sm">{session.user.name}</p>
    74→							<p className="text-muted-foreground truncate text-xs">{session.user.email}</p>
    75→						</div>
    76→					</DropdownMenuLabel>
    77→					<DropdownMenuSeparator />
    78→					<DropdownMenuItem
